namespace CleanArchitecture.Blazor.Application.Features.Subsystems.EventHandlers;

public class SubsystemUpdatedEventHandler : INotificationHandler<SubsystemUpdatedEvent>
{
    private readonly ILogger<SubsystemUpdatedEventHandler> _logger;

    public SubsystemUpdatedEventHandler(
        ILogger<SubsystemUpdatedEventHandler> logger
    )
    {
        _logger = logger;
    }

    public Task Handle(SubsystemUpdatedEvent notification, CancellationToken cancellationToken)
    {
        _logger.LogInformation("Subsystem updated: {SubsystemName} (ID: {SubsystemId}) under System ID: {SystemId} by {UpdatedBy} at {UpdatedOn}", 
            notification.Item.Name, 
            notification.Item.Id,
            notification.Item.SystemId,
            notification.Item.LastModifiedBy, 
            notification.Item.LastModified);
        
        return Task.CompletedTask;
    }
}